using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
// Separate Design Sheet: Beam Deflection Check from STAAD.Pro node coordinates, member incidences and node displacements.
class BeamDeflectionForm:DesignSheetForm {
 internal const string Requirements=
 "WHAT THIS SHEET NEEDS FROM STAAD.Pro\r\n\r\n"+
 "1. NODE COORDINATES - Node, X, Y, Z (Geometry > Nodes table, or the .STD file).\r\n"+
 "2. MEMBER INCIDENCES - Member/Beam, Node A, Node B (Geometry > Beams table, or the .STD file).\r\n"+
 "3. NODE DISPLACEMENTS - Node, L/C, X, Y, Z translations (Post-Processing > Node Displacements table, a CSV/Excel export, or the .ANL output file).\r\n"+
 "   Include every node of each beam you will check: BOTH supports and ALL intermediate nodes, for the service (unfactored) load cases.\r\n\r\n"+
 "STAAD INPUT COMMANDS (when you want to import the .ANL file)\r\n"+
 "   PERFORM ANALYSIS\r\n"+
 "   PRINT JOINT DISPLACEMENTS LIST <nodes>      (or ALL)\r\n"+
 "   Use service load cases or service combinations (for example DL, LL, DL+LL). Factored strength combinations are not deflection checks.\r\n\r\n"+
 "MODELLING TIPS\r\n"+
 "   - Deflection is read at analysis nodes only. Split long beams in STAAD (for example at quarter or tenth points) so the midspan maximum is sampled.\r\n"+
 "   - JOINT COORDINATES and MEMBER INCIDENCES must be written out (expanded). REPEAT / generated geometry: export the Nodes and Beams tables instead.\r\n"+
 "   - Units: headings such as 'X (mm)' or the STAAD UNIT command are detected automatically; otherwise choose the unit on each tab.\r\n"+
 "   - Default deflection direction is global Y; models with SET Z UP switch to global Z when imported.\r\n\r\n"+
 "THEN\r\n"+
 "   Beams to check: list each physical beam as its STAAD member numbers (for example 12, 13, 14 or 12-14) between two real supports, its load cases and its limit L/n.\r\n"+
 "   Suggest beam lines proposes straight collinear member chains split at columns/posts and support nodes; confirm them before use.\r\n"+
 "   Calculate shows the results; Export PDF / Print preview / Export report file produce the calculation report.";
 readonly DataGridView groups=new DataGridView{Width=1050,Height=300,Tag="FullWidth",AllowUserToAddRows=true,AllowUserToDeleteRows=true,MultiSelect=true,RowHeadersVisible=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None};
 readonly DataGridView output=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
 readonly TextBox loaded=new TextBox{Multiline=true,ReadOnly=true,Width=1050,Height=110,Tag="FullWidth",ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.FixedSingle};
 TextBox coordinates,members,displacements,geometrySource,resultSource;readonly List<BeamDeflectionResult> latest=new List<BeamDeflectionResult>();BeamDeflectionSummary summary=new BeamDeflectionSummary();readonly HashSet<int> supportNodes=new HashSet<int>();
 static readonly string[] Criteria={"L/360 - floor, immediate live load","L/240 - after attachment, nonstructural not likely damaged","L/480 - after attachment, nonstructural likely damaged","L/180 - flat roof, immediate live load","Custom - enter L/n per beam"};
 const int CName=0,CMembers=1,CType=2,CStart=3,CEnd=4,CCases=5,CRatio=6,CAbsolute=7,CSpan=8,CMax=9,CLimit=10,CStatus=11;
 public BeamDeflectionForm():base("Beam Deflection Check | STAAD.Pro results","Beam-Deflection"){
  var guide=Section("STAAD input requirements","");var text=new TextBox{Multiline=true,ReadOnly=true,Width=1050,Height=430,Tag="FullWidth",ScrollBars=ScrollBars.Vertical,Font=new Font("Consolas",9.5f),Text=Requirements,BorderStyle=BorderStyle.FixedSingle};guide.Controls.Add(text);guide.Controls.Add(new Label{Text="Loaded data",Width=1050,Height=26,Tag="FullWidth",Font=ModernUi.Strong});guide.Controls.Add(loaded);
  var geometry=Section("STAAD model geometry","Import the .STD file, the STAAD Nodes/Beams tables (CSV, Excel or pasted), or the .ANL file when it echoes the input. Units in the table headings or the STAAD UNIT command take precedence over the unit selected here.");
  Choice(geometry,"GeometryUnit","Coordinate unit (when not stated in the data)",StaadDisplacements.Units);geometrySource=NumberField(geometry,"GeometrySource","Imported geometry file","");geometrySource.ReadOnly=true;
  var geometryActions=new FlowLayoutPanel{Width=1050,Height=46,Tag="FullWidth"};Action(geometryActions,"Import STAAD .STD model",ImportModel);Action(geometryActions,"Import Nodes table (CSV / Excel)",()=>ImportTable(coordinates,"coordinates"));Action(geometryActions,"Import Beams table (CSV / Excel)",()=>ImportTable(members,"members"));Action(geometryActions,"Paste Nodes table",()=>Paste(coordinates));Action(geometryActions,"Paste Beams table",()=>Paste(members));geometry.Controls.Add(geometryActions);
  coordinates=TableInput(geometry,"Coordinates","Node coordinates - Node, X, Y, Z");members=TableInput(geometry,"Members","Member incidences - Member (Beam), Node A, Node B");
  var results=Section("STAAD node displacements","Post-Processing > Node Displacements: select the service load cases, copy the table with its headings and paste it here, or import a CSV/Excel export or the .ANL output (PRINT JOINT DISPLACEMENTS). Only X, Y, Z translations are used; rotations are ignored.");
  Choice(results,"DisplacementUnit","Translation unit (when not stated in the data)",new[]{"mm","cm","m","in","ft"});resultSource=NumberField(results,"ResultSource","Imported results file","");resultSource.ReadOnly=true;
  var actions=new FlowLayoutPanel{Width=1050,Height=46,Tag="FullWidth"};Action(actions,"Paste Node Displacements table",()=>Paste(displacements));Action(actions,"Import CSV / Excel results",()=>ImportTable(displacements,"displacements"));Action(actions,"Import STAAD .ANL output",ImportAnl);results.Controls.Add(actions);
  displacements=TableInput(results,"Displacements","Node displacements - Node, L/C, X, Y, Z translations");
  var beams=Section("Beams to check","One row per physical beam between two real supports. Intermediate nodes inside a beam are deflection stations, not supports. Repeat a beam on another row to check it against a different limit (for example live load L/360 and total load L/240).");
  Choice(beams,"Vertical","Deflection direction (global axis)",new[]{"Y","Z","X"});Choice(beams,"Criterion","Default limit for new rows",Criteria);Toggle(beams,"ServiceBasis","Selected load cases are service (unfactored) loads",false);Toggle(beams,"SupportsVerified","Support A / B are the real supports of each beam",false);
  groups.Columns.Add("Beam","Beam ID");groups.Columns.Add("Members","STAAD member IDs (12, 13, 14 or 12-14)");var type=new DataGridViewComboBoxColumn{Name="SpanType",HeaderText="Span type",FlatStyle=FlatStyle.Flat,DisplayStyleForCurrentCellOnly=true};type.Items.AddRange(BeamDeflection.SpanTypes);groups.Columns.Add(type);
  foreach(var c in new[]{new[]{"StartNode","Support A node (blank = lower end)"},new[]{"EndNode","Support B node (blank = other end)"},new[]{"Cases","Load cases (blank = all)"},new[]{"Ratio","Limit n in L/n"},new[]{"Absolute","Absolute limit mm (optional)"},new[]{"Span","Span m"},new[]{"Max","Max |δrel| mm"},new[]{"Limit","δallow mm"},new[]{"Status","Result"}})groups.Columns.Add(c[0],c[1]);
  for(int i=CSpan;i<=CStatus;i++){groups.Columns[i].ReadOnly=true;groups.Columns[i].DefaultCellStyle.BackColor=Color.FromArgb(242,244,246);}
  int[] widths={80,200,170,110,110,130,80,100,80,90,80,360};for(int i=0;i<widths.Length;i++)groups.Columns[i].Width=widths[i];groups.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize;groups.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;
  groups.DefaultValuesNeeded+=(s,e)=>{e.Row.Cells[CType].Value=BeamDeflection.SpanTypes[0];double n=DefaultRatio();if(n>0)e.Row.Cells[CRatio].Value=n.ToString(CultureInfo.InvariantCulture);};
  groups.DataError+=(s,e)=>{e.ThrowException=false;};
  GridAppearance.Apply(groups);RowDeleteAffordance.Attach(groups);GridEditHistory.Configure(groups,()=>Restoring,value=>Restoring=value,()=>{});beams.Controls.Add(groups);
  var edits=new FlowLayoutPanel{Width=1050,Height=46,Tag="FullWidth"};GridEditHistory.AddCommands(this,edits);Action(edits,"Suggest beam lines from geometry",Suggest);Action(edits,"Show load cases",ShowCases);beams.Controls.Add(edits);
  var page=new TabPage("Deflection results");foreach(string name in BeamDeflectionReport.SummaryHeaders)output.Columns.Add(name,name);output.Columns[output.ColumnCount-1].FillWeight=70;GridAppearance.Apply(output);page.Controls.Add(output);AddResultPage(page);
  foreach(var box in new[]{coordinates,members,displacements})box.TextChanged+=(s,e)=>{if(!Restoring)RefreshLoaded();};RefreshLoaded();Pages.SelectedIndex=0;}
 double DefaultRatio(){string c=Value("Criterion");if(c.StartsWith("Custom"))return 0;return double.Parse(c.Substring(2,3),CultureInfo.InvariantCulture);}
 TextBox TableInput(FlowLayoutPanel panel,string key,string title){panel.Controls.Add(new Label{Text=title,Width=1050,Height=26,Tag="FullWidth",Font=ModernUi.Strong});var text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1050,Height=200,Tag="FullWidth",Font=new Font("Consolas",9),MaxLength=0};Inputs.Add(key,text);panel.Controls.Add(text);return text;}
 void Action(FlowLayoutPanel panel,string caption,System.Action action){var button=new Button{Text=caption,AutoSize=true,Height=32};button.Click+=(s,e)=>{try{action();}catch(Exception error){MessageBox.Show(this,error.Message,caption);}};panel.Controls.Add(button);}
 void Paste(TextBox target){if(!Clipboard.ContainsText())throw new Exception("The clipboard has no table text. Copy the STAAD table (including headings) first.");target.Text=Clipboard.GetText();}
 protected override bool OptionalSavedInput(string key){return key=="GeometrySource"||key=="ResultSource"||key=="Criterion";}
 BeamDeflectionData Data(){var data=new BeamDeflectionData();if(coordinates.Text.Trim()=="")throw new Exception("Node coordinates are missing. See the STAAD input requirements tab.");if(members.Text.Trim()=="")throw new Exception("Member incidences are missing. See the STAAD input requirements tab.");if(displacements.Text.Trim()=="")throw new Exception("Node displacements are missing. See the STAAD input requirements tab.");StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);StaadDisplacements.Displacements(data,displacements.Text,Value("DisplacementUnit"));return data;}
 void RefreshLoaded(){var lines=new List<string>();Func<string,Action<BeamDeflectionData>,string> probe=(label,read)=>{try{var d=new BeamDeflectionData();read(d);return label+": OK";}catch(Exception ex){return label+": "+ex.Message;}};
  if(coordinates.Text.Trim()==""&&members.Text.Trim()==""&&displacements.Text.Trim()==""){loaded.Text="Nothing loaded yet. Provide node coordinates, member incidences and node displacements.";return;}
  try{var d=new BeamDeflectionData();StaadDisplacements.Coordinates(d,coordinates.Text,Value("GeometryUnit"));lines.Add("Node coordinates: "+d.Nodes.Count+" nodes; unit from "+d.GeometryUnitSource+".");}catch(Exception ex){lines.Add("Node coordinates: "+ex.Message);}
  try{var d=new BeamDeflectionData();StaadDisplacements.Members(d,members.Text);lines.Add("Member incidences: "+d.Members.Count+" members.");}catch(Exception ex){lines.Add("Member incidences: "+ex.Message);}
  try{var d=new BeamDeflectionData();StaadDisplacements.Displacements(d,displacements.Text,Value("DisplacementUnit"));var cases=d.Cases().ToList();lines.Add("Node displacements: "+d.Displacements.Count+" rows, "+d.Displacements.Select(x=>x.Node).Distinct().Count()+" nodes, "+cases.Count+" load case(s): "+string.Join(", ",cases.Take(12))+(cases.Count>12?" ...":"")+"; unit from "+d.DisplacementUnitSource+".");}catch(Exception ex){lines.Add("Node displacements: "+ex.Message);}
  loaded.Text=string.Join("\r\n",lines);}
 static string N(double n){return n.ToString("0.#########",CultureInfo.InvariantCulture);}
 static string NodesText(BeamDeflectionData data,double unit,string name){return "Node\tX ("+name+")\tY ("+name+")\tZ ("+name+")\r\n"+string.Join("\r\n",data.Nodes.Values.OrderBy(n=>n.Id).Select(n=>n.Id+"\t"+N(n.X/unit)+"\t"+N(n.Y/unit)+"\t"+N(n.Z/unit)));}
 static string MembersText(BeamDeflectionData data){return "Beam\tNode A\tNode B\r\n"+string.Join("\r\n",data.Members.Values.OrderBy(m=>m.Id).Select(m=>m.Id+"\t"+m.A+"\t"+m.B));}
 static string ResultText(BeamDeflectionData data,double unit,string name){return "Node\tL/C\tX ("+name+")\tY ("+name+")\tZ ("+name+")\r\n"+string.Join("\r\n",data.Displacements.OrderBy(d=>d.Node).Select(d=>d.Node+"\t"+d.Case+"\t"+N(d.X/unit)+"\t"+N(d.Y/unit)+"\t"+N(d.Z/unit)));}
 void ApplyGeometry(BeamDeflectionData data,string file){string unit=Value("GeometryUnit");coordinates.Text=NodesText(data,StaadDisplacements.Unit(unit),unit);members.Text=MembersText(data);geometrySource.Text=Path.GetFileName(file);if(data.ZUp)Inputs["Vertical"].Text="Z";}
 void ImportModel(){using(var dialog=new OpenFileDialog{Filter="STAAD model|*.std;*.txt|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();supportNodes.Clear();StaadDisplacements.Model(data,File.ReadAllText(dialog.FileName),Value("GeometryUnit"),supportNodes);if(data.Nodes.Count==0||data.Members.Count==0)throw new Exception("No expanded JOINT COORDINATES / MEMBER INCIDENCES found in the file.");ApplyGeometry(data,dialog.FileName);MessageBox.Show(this,"Imported "+data.Nodes.Count+" nodes and "+data.Members.Count+" members (unit from "+data.GeometryUnitSource+")."+(data.ZUp?" SET Z UP found: deflection direction set to global Z.":""),"STAAD model");}}
 void ImportAnl(){using(var dialog=new OpenFileDialog{Filter="STAAD analysis output|*.anl;*.txt|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();StaadDisplacements.Anl(data,File.ReadAllText(dialog.FileName),Value("GeometryUnit"),Value("DisplacementUnit"));if(data.Nodes.Count>0&&data.Members.Count>0)ApplyGeometry(data,dialog.FileName);string unit=Value("DisplacementUnit");displacements.Text=ResultText(data,StaadDisplacements.Unit(unit),unit);resultSource.Text=Path.GetFileName(dialog.FileName);MessageBox.Show(this,"Imported "+data.Displacements.Count+" node displacement rows for "+data.Cases().Count()+" load case(s); unit from "+data.DisplacementUnitSource+"."+(data.Nodes.Count>0?" Geometry was also read from the input echo.":" Geometry was not echoed; import the .STD model or the Nodes/Beams tables."),"STAAD output");}}
 void ImportTable(TextBox target,string kind){using(var dialog=new OpenFileDialog{Filter="STAAD tables|*.csv;*.tsv;*.txt;*.xlsx;*.xlsm|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){string ext=Path.GetExtension(dialog.FileName).ToLowerInvariant();var candidates=ext==".xlsx"||ext==".xlsm"?StaadSpreadsheet.Tables(dialog.FileName).Values.ToList():new List<string>{File.ReadAllText(dialog.FileName)};Exception last=null;
  foreach(string text in candidates){try{var data=new BeamDeflectionData();if(kind=="coordinates")StaadDisplacements.Coordinates(data,text,Value("GeometryUnit"));else if(kind=="members")StaadDisplacements.Members(data,text);else StaadDisplacements.Displacements(data,text,Value("DisplacementUnit"));target.Text=text;if(kind=="displacements")resultSource.Text=Path.GetFileName(dialog.FileName);else geometrySource.Text=Path.GetFileName(dialog.FileName);return;}catch(Exception error){last=error;}}
  throw new Exception("No usable "+kind+" table found. "+(last==null?"":last.Message));}}
 void Suggest(){var data=new BeamDeflectionData();StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);var found=BeamDeflection.SuggestGroups(data,Value("Vertical"));if(found.Count==0)throw new Exception("No straight beam lines with intermediate nodes were found perpendicular to global "+Value("Vertical")+".");
  var existing=new HashSet<string>(groups.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>Cell(r,CMembers)));int added=0;double n=DefaultRatio();foreach(var item in found){string list=string.Join(", ",item.Value);if(existing.Contains(list))continue;groups.Rows.Add(item.Key,list,BeamDeflection.SpanTypes[0],"","","",n>0?n.ToString(CultureInfo.InvariantCulture):"","");added++;}
  MessageBox.Show(this,added+" beam line(s) added. They are split where columns/posts meet the beam. Confirm Support A/B, delete lines you do not need, and enter load cases.","Suggest beam lines");}
 void ShowCases(){var d=new BeamDeflectionData();StaadDisplacements.Displacements(d,displacements.Text,Value("DisplacementUnit"));MessageBox.Show(this,string.Join("\r\n",d.Cases()),"Load cases in the displacement table");}
 static string Cell(DataGridViewRow row,int col){return Convert.ToString(row.Cells[col].Value,CultureInfo.InvariantCulture).Trim();}
 void Evaluate(){groups.EndEdit();var data=Data();latest.Clear();output.Rows.Clear();var errors=new List<string>();var vertical=Value("Vertical");bool service=((CheckBox)Inputs["ServiceBasis"]).Checked,supports=((CheckBox)Inputs["SupportsVerified"]).Checked;
  foreach(DataGridViewRow row in groups.Rows){if(row.IsNewRow||Cell(row,CMembers)=="")continue;for(int c=CSpan;c<=CStatus;c++)row.Cells[c].Value="";row.Cells[CStatus].Style.ForeColor=Color.Empty;
   try{string ratio=Cell(row,CRatio);if(ratio=="")throw new Exception("Enter the limit n for L/n.");string type=Cell(row,CType);var input=new PhysicalBeamInput{Name=Cell(row,CName)==""?"B"+(row.Index+1):Cell(row,CName),Members=Cell(row,CMembers),SpanType=type==""?BeamDeflection.SpanTypes[0]:type,Start=Cell(row,CStart)==""?0:StaadDisplacements.Id(Cell(row,CStart)),End=Cell(row,CEnd)==""?0:StaadDisplacements.Id(Cell(row,CEnd)),Cases=Cell(row,CCases),LimitRatio=StaadDisplacements.Number(ratio),AbsoluteLimitMm=Cell(row,CAbsolute)==""?0:StaadDisplacements.Number(Cell(row,CAbsolute)),Vertical=vertical,ServiceBasis=service,SupportsVerified=supports};
    var values=BeamDeflection.Calculate(data,input);latest.AddRange(values);var worst=values.OrderByDescending(v=>v.Utilization).First();row.Cells[CSpan].Value=worst.Span.ToString("F3",CultureInfo.InvariantCulture);row.Cells[CMax].Value=worst.MaximumMm.ToString("F2",CultureInfo.InvariantCulture);row.Cells[CLimit].Value=worst.LimitMm.ToString("F2",CultureInfo.InvariantCulture);row.Cells[CStatus].Value=(values.Count>1?"Governing LC "+worst.Case+": ":"")+worst.Status;row.Cells[CStatus].Style.ForeColor=worst.Exceeds?Color.Firebrick:worst.Qualified?PowTheme.Teal:Color.DarkGoldenrod;
    foreach(var value in values)output.Rows.Add(BeamDeflectionReport.SummaryRow(value));}
   catch(Exception error){row.Cells[CStatus].Value=error.Message;row.Cells[CStatus].Style.ForeColor=Color.Firebrick;errors.Add("Row "+(row.Index+1)+": "+error.Message);}}
  if(errors.Count>0)throw new Exception(string.Join("\r\n",errors));if(latest.Count==0)throw new Exception("Add at least one beam on the Beams to check tab (STAAD member IDs).");
  summary=new BeamDeflectionSummary{GeometrySource=geometrySource.Text,ResultSource=resultSource.Text,GeometryUnit=data.GeometryUnitSource,DisplacementUnit=data.DisplacementUnitSource,Vertical=vertical,ZUp=vertical=="Z",ServiceBasis=service,SupportsVerified=supports,Nodes=data.Nodes.Count,Members=data.Members.Count,Cases=data.Cases().ToList(),Criteria=Value("Criterion")};}
 protected override string BuildReport(){Evaluate();return BeamDeflectionReport.Text(summary,latest);}
 protected override EngineeringReport BuildEngineeringReport(){Evaluate();return BeamDeflectionReport.Create(summary,latest);}
 protected override CalculationDocument BuildDocument(){var report=BuildEngineeringReport();var document=CalculationDocument.FromEngineering(report);BeamDeflectionReport.AddShapeSheets(document,latest);return document;}
 protected override void WriteAdditionalState(XmlElement root){var table=root.OwnerDocument.CreateElement("BeamGroups");table.SetAttribute("version","2");root.AppendChild(table);foreach(DataGridViewRow row in groups.Rows)if(!row.IsNewRow&&Cell(row,CMembers)!=""){var item=root.OwnerDocument.CreateElement("Beam");for(int c=0;c<=CAbsolute;c++)item.SetAttribute("c"+c,Cell(row,c));table.AppendChild(item);}}
 protected override void ReadAdditionalState(XmlElement root){var table=root["BeamGroups"];if(table==null||table.GetAttribute("version")!="2")throw new Exception("Missing or unsupported beam list in the saved sheet.");var rows=new List<object[]>();foreach(XmlElement row in table.SelectNodes("Beam")){var values=Enumerable.Range(0,CAbsolute+1).Select(c=>(object)row.GetAttribute("c"+c)).ToArray();if(!BeamDeflection.SpanTypes.Contains(Convert.ToString(values[CType])))values[CType]=BeamDeflection.SpanTypes[0];rows.Add(values);}
  bool was=Restoring;Restoring=true;try{groups.Rows.Clear();foreach(var values in rows)groups.Rows.Add(values);}finally{Restoring=was;}}
 protected override void AfterRestore(){RefreshLoaded();}
}
}
